const copyResponse = $('Generate Slide Copy').first().json;
const meta = $('Build Extract Prompt').first().json;
const content = copyResponse.choices?.[0]?.message?.content;
if (!content) throw new Error('No content from GPT-4o: ' + JSON.stringify(copyResponse));
let parsed;
try { parsed = JSON.parse(content); } catch (e) { throw new Error('Invalid JSON: ' + content.substring(0, 500)); }
const slides = parsed.slides;
if (!slides || !Array.isArray(slides) || slides.length === 0) throw new Error('No slides in response');
const colors = parsed.colors || { primaryColor: '#1a1a2e', accentColor: '#3b82f6', textColor: '#ffffff' };
const ts = Date.now();
const brandId = meta.brandId;

let templateSlides = [];
try {
  const layoutData = $('Fetch Layout').first().json;
  templateSlides = layoutData?.carousel_slide_prompts || [];
} catch(e) { templateSlides = []; }

const enriched = slides.slice(0, 6).map((slide, i) => {
  const splitPercent = slide.splitPercent || (slide.slideType === 'title' ? 65 : slide.slideType === 'cta' ? 80 : 50);
  const imageSidePct = 100 - splitPercent;
  const templateSlide = templateSlides.find(t => t.slide_index === i + 1);
  const cfg = templateSlide?.puppeteer_config || null;

  const brandStyle = (meta.stylePrompt || '').substring(0, 1500);
  const slideContext = [slide.headline, slide.subhead, ...(slide.bullets || [])].filter(Boolean).join('. ');
  const fallbackBgPrompt = `Cinematic, high-quality background photograph for a LinkedIn carousel slide. ${slide.visualContext || ''} The LEFT ${splitPercent}% of the frame should be relatively clean, uncluttered, and low contrast. Concentrate visual interest in the RIGHT ${imageSidePct}% of the frame. No text, no logos, no UI elements. Professional editorial photography quality. Square 1:1 format.`;
  const baseBgPrompt = (templateSlide?.prompt && templateSlide.prompt.trim()) ? `${templateSlide.prompt}\n\nVisual context: ${slide.visualContext || ''}` : fallbackBgPrompt;
  const bgPrompt = `${baseBgPrompt}

BRAND STYLE GUIDE (use for colors, mood, visual language):
${brandStyle}

SLIDE TOPIC CONTEXT (visual should reflect this, do NOT render as text):
${slideContext}`;

  const requestBody = JSON.stringify({
    model: 'gpt-image-2',
    prompt: bgPrompt,
    n: 1,
    size: '1024x1024',
    quality: 'medium'
  });

  const storagePath = `${brandId}/${ts}_v2_carousel_slide_${i}.png`;
  const imageUrl = null; // set from ImageKit upload response

  const puppeteerConfig = {
    headlineSize: cfg?.headlineSize || null,
    microcopySize: cfg?.microcopySize || null,
    verticalAlign: cfg?.verticalAlign || null,
    logoPosition: cfg?.logoPosition || slide.logoPos || 'bottom-left',
    logoX: cfg?.logoX ?? null,
    logoY: cfg?.logoY ?? null,
    logoSize: cfg?.logoSize || 48,
    headlineX: cfg?.headlineX ?? null,
    headlineY: cfg?.headlineY ?? null,
    microcopyX: cfg?.microcopyX ?? null,
    microcopyY: cfg?.microcopyY ?? null,
    accentColor: cfg?.accentColor || colors.accentColor,
    primaryColor: cfg?.bgColor || colors.primaryColor,
    textColor: cfg?.headlineColor || colors.textColor,
    microcopyColor: cfg?.microcopyColor || null,
    bulletSize: cfg?.bulletSize || null,
    customFontDataUrl: cfg?.customFontDataUrl || null,
    fontFamily: cfg?.fontFamily || null,
    headlineFontFamily: cfg?.headlineFontFamily || null,
    headlineCustomFontDataUrl: cfg?.headlineCustomFontDataUrl || null,
    eyebrowFontFamily: cfg?.eyebrowFontFamily || null,
    eyebrowCustomFontDataUrl: cfg?.eyebrowCustomFontDataUrl || null,
    microcopyFontFamily: cfg?.microcopyFontFamily || null,
    microcopyCustomFontDataUrl: cfg?.microcopyCustomFontDataUrl || null,
    bulletFontFamily: cfg?.bulletFontFamily || null,
    bulletCustomFontDataUrl: cfg?.bulletCustomFontDataUrl || null,
    ctaFontFamily: cfg?.ctaFontFamily || null,
    ctaCustomFontDataUrl: cfg?.ctaCustomFontDataUrl || null,
    eyebrowSize: cfg?.eyebrowSize || null,
    eyebrowUppercase: cfg?.eyebrowUppercase ?? null,
    ctaPosition: cfg?.ctaPosition || null,
    ctaStyle: cfg?.ctaStyle || null,
    logoDataUrl: cfg?.logoDataUrl || null,
    padding: cfg?.padding || 60,
    removeBg: cfg?.removeBg || false,
    elements: cfg?.elements || [],
    splitPercent: cfg?.splitPercent ?? null,
    textX: cfg?.textX ?? null,
    textY: cfg?.textY ?? null,
  };

  return { requestBody, storagePath, imageUrl, originalSlide: { ...slide, _colors: colors, _cfg: puppeteerConfig } };
});

return [{ json: { slides: enriched, colors, brandId: meta.brandId, jobId: meta.jobId, logoUrl: meta.logoUrl, timestamp: ts } }];

const r = $input.first().json;
const meta = $('Parse Slides').first().json;
const i = 0;
const b64 = r.data?.[0]?.b64_json;
if (!b64) throw new Error('Slide 0: no image data: ' + JSON.stringify(r));
const storagePath = meta.slides[i].storagePath;
const imageUrl = meta.slides[i].imageUrl;
const binaryData = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), `slide_${i}.png`, 'image/png');
return [{ json: { slideIndex: i, storagePath, imageUrl }, binary: { data: binaryData } }];

